const selectSandboxProfile = `-- name: SelectSandboxProfile :one
SELECT profile.id, profile.name, profile.backend_id, profile.image_id, profile.task_kinds, profile.cpu_millis, profile.memory_mib, profile.timeout_seconds, profile.network_mode, profile.status, profile.revision, profile.version, profile.created_at, profile.updated_at FROM sandbox_profiles profile
JOIN sandbox_backends backend ON backend.id = profile.backend_id AND backend.status = 'enabled'
JOIN sandbox_images image ON image.id = profile.image_id AND image.status = 'enabled'
WHERE profile.status = 'enabled' AND $1::text = ANY(profile.task_kinds)
ORDER BY profile.name, profile.id LIMIT 1
`

